   390→	if ok, err := dv.results.cached(RequireSidecarKzgProofVerified); ok {
   391→		return err
   392→	}
   393→
   394→	defer dv.recordResult(RequireSidecarKzgProofVerified, &err)
   395→
   396→	startTime := time.Now()
   397→
   398→	err = dv.verifyDataColumnsCommitment(dv.dataColumns)
   399→	if err != nil {
   400→		return columnErrBuilder(errors.Wrap(err, "verify data column commitment"))
   401→	}
   402→
   403→	dataColumnBatchKZGVerificationHistogram.Observe(float64(time.Since(startTime).Milliseconds()))
   404→	return nil
   405→}
   406→
   407→func (dv *RODataColumnsVerifier) SidecarProposerExpected(ctx context.Context) (err error) {
   408→	if ok, err := dv.results.cached(RequireSidecarProposerExpected); ok {
   409→		return err
   410→	}
   411→
   412→	defer dv.recordResult(RequireSidecarProposerExpected, &err)
   413→
   414→	type slotParentRoot struct {
   415→		slot       primitives.Slot
   416→		parentRoot [fieldparams.RootLength]byte
   417→	}
   418→
   419→	targetRootBySlotParentRoot := make(map[slotParentRoot][fieldparams.RootLength]byte)
   420→
   421→	var targetRootFromCache = func(slot primitives.Slot, parentRoot [fieldparams.RootLength]byte) ([fieldparams.RootLength]byte, error) {
   422→		// Use cached values if available.
   423→		slotParentRoot := slotParentRoot{slot: slot, parentRoot: parentRoot}
   424→		if root, ok := targetRootBySlotParentRoot[slotParentRoot]; ok {
   425→			return root, nil
   426→		}
   427→
   428→		// Compute the epoch of the data column slot.
   429→		dataColumnEpoch := slots.ToEpoch(slot)
   430→		if dataColumnEpoch > 0 {
   431→			dataColumnEpoch = dataColumnEpoch - 1
   432→		}
   433→
   434→		// Compute the target root for the epoch.
   435→		targetRoot, err := dv.fc.TargetRootForEpoch(parentRoot, dataColumnEpoch)
   436→		if err != nil {
   437→			return [fieldparams.RootLength]byte{}, columnErrBuilder(errors.Wrap(err, "target root from epoch"))
   438→		}
   439→
   440→		// Store the target root in the cache.
   441→		targetRootBySlotParentRoot[slotParentRoot] = targetRoot
   442→
   443→		return targetRoot, nil
   444→	}
   445→
   446→	for _, dataColumn := range dv.dataColumns {
   447→		// Extract the slot of the data column.
   448→		dataColumnSlot := dataColumn.Slot()
   449→
   450→		// Extract the root of the parent block corresponding to the data column.
   451→		parentRoot := dataColumn.ParentRoot()
   452→
   453→		// Compute the target root for the data column.
   454→		targetRoot, err := targetRootFromCache(dataColumnSlot, parentRoot)
   455→		if err != nil {
   456→			return columnErrBuilder(errors.Wrap(err, "target root"))
   457→		}
   458→
   459→		// Compute the epoch of the data column slot.
   460→		dataColumnEpoch := slots.ToEpoch(dataColumnSlot)
   461→		if dataColumnEpoch > 0 {
   462→			dataColumnEpoch = dataColumnEpoch - 1
   463→		}
   464→
   465→		// Create a checkpoint for the target root.
   466→		checkpoint := &forkchoicetypes.Checkpoint{Root: targetRoot, Epoch: dataColumnEpoch}
   467→
   468→		// Try to extract the proposer index from the data column in the cache.
   469→		idx, cached := dv.pc.Proposer(checkpoint, dataColumnSlot)
   470→
   471→		if !cached {
   472→			// Retrieve the parent state.
   473→			parentState, err := dv.parentState(ctx, dataColumn)
   474→			if err != nil {
   475→				return columnErrBuilder(errors.Wrap(err, "parent state"))
   476→			}
   477→
   478→			idx, err = dv.pc.ComputeProposer(ctx, parentRoot, dataColumnSlot, parentState)
   479→			if err != nil {
   480→				return columnErrBuilder(errors.Wrap(err, "compute proposer"))
   481→			}
   482→		}
   483→
   484→		if idx != dataColumn.ProposerIndex() {
   485→			return columnErrBuilder(errSidecarUnexpectedProposer)
   486→		}
   487→	}
   488→
   489→	return nil
   490→}
   491→
   492→// parentState retrieves the parent state of the data column from the cache if possible, else retrieves it from the state by rooter.
   493→func (dv *RODataColumnsVerifier) parentState(ctx context.Context, dataColumn blocks.RODataColumn) (state.BeaconState, error) {
   494→	parentRoot := dataColumn.ParentRoot()
   495→
   496→	// If the parent root is already in the cache, return it.
   497→	if st, ok := dv.stateByRoot[parentRoot]; ok {
   498→		return st, nil
   499→	}
   500→
   501→	// Retrieve the parent state from the state by rooter.
   502→	st, err := dv.sr.StateByRoot(ctx, parentRoot)
   503→	if err != nil {
   504→		return nil, errors.Wrap(err, "state by root")
   505→	}
   506→
   507→	// Store the parent state in the cache.
   508→	dv.stateByRoot[parentRoot] = st
   509→
   510→	return st, nil
   511→}
   512→
   513→func columnToSignatureData(d blocks.RODataColumn) signatureData {
   514→	return signatureData{
   515→		Root:      d.BlockRoot(),
   516→		Parent:    d.ParentRoot(),
   517→		Signature: bytesutil.ToBytes96(d.SignedBlockHeader.Signature),
   518→		Proposer:  d.ProposerIndex(),
   519→		Slot:      d.Slot(),
   520→	}
   521→}
   522→
   523→func columnErrBuilder(baseErr error) error {
   524→	return errors.Wrap(baseErr, errColumnsInvalid.Error())
   525→}
   526→
   527→func inclusionProofKey(c blocks.RODataColumn) ([160]byte, error) {
   528→	var key [160]byte
   529→	if len(c.KzgCommitmentsInclusionProof) != 4 {
   530→		// This should be already enforced by ssz unmarshaling; still check so we don't panic on array bounds.
   531→		return key, columnErrBuilder(ErrSidecarInclusionProofInvalid)
   532→	}
   533→
   534→	root, err := c.SignedBlockHeader.HashTreeRoot()
   535→	if err != nil {
   536→		return [160]byte{}, columnErrBuilder(errors.Wrap(err, "hash tree root"))
   537→	}
   538→
   539→	for i := range c.KzgCommitmentsInclusionProof {
   540→		if copy(key[32*i:32*i+32], c.KzgCommitmentsInclusionProof[i]) != 32 {
   541→			return key, columnErrBuilder(ErrSidecarInclusionProofInvalid)
   542→		}
   543→	}
   544→
   545→	copy(key[128:], root[:])
   546→	return key, nil
   547→}
