     1→package blocks
     2→
     3→import (
     4→	field_params "github.com/OffchainLabs/prysm/v6/config/fieldparams"
     5→	"github.com/OffchainLabs/prysm/v6/config/params"
     6→	"github.com/OffchainLabs/prysm/v6/consensus-types/interfaces"
     7→	"github.com/OffchainLabs/prysm/v6/container/trie"
     8→	"github.com/OffchainLabs/prysm/v6/encoding/ssz"
     9→	"github.com/OffchainLabs/prysm/v6/runtime/version"
    10→	"github.com/pkg/errors"
    11→	"github.com/prysmaticlabs/gohashtree"
    12→)
    13→
    14→const (
    15→	bodyLength    = 13 // The number of elements in the BeaconBlockBody Container for Electra
    16→	logBodyLength = 4  // The log 2 of bodyLength
    17→	kzgPosition   = 11 // The index of the KZG commitment list in the Body
    18→	kzgRootIndex  = 54 // The Merkle index of the KZG commitment list's root in the Body's Merkle tree
    19→	KZGOffset     = kzgRootIndex * field_params.MaxBlobCommitmentsPerBlock
    20→)
    21→
    22→var (
    23→	errInvalidIndex          = errors.New("index out of bounds")
    24→	errInvalidBodyRoot       = errors.New("invalid Beacon Block Body root")
    25→	errInvalidInclusionProof = errors.New("invalid KZG commitment inclusion proof")
    26→)
    27→
    28→// MerkleProofComponents contains pre-computed components for efficient proof generation
    29→type MerkleProofComponents struct {
    30→	kzgSubtree    *trie.SparseMerkleTrie
    31→	topLevelProof [][]byte
    32→}
    33→
    34→// VerifyKZGInclusionProof verifies the Merkle proof in a Blob sidecar against
    35→// the beacon block body root.
    36→func VerifyKZGInclusionProof(blob ROBlob) error {
    37→	if blob.SignedBlockHeader == nil {
    38→		return errNilBlockHeader
    39→	}
    40→	if blob.SignedBlockHeader.Header == nil {
    41→		return errNilBlockHeader
    42→	}
    43→	root := blob.SignedBlockHeader.Header.BodyRoot
    44→	if len(root) != field_params.RootLength {
    45→		return errInvalidBodyRoot
    46→	}
    47→	chunks := makeChunk(blob.KzgCommitment)
    48→	gohashtree.HashChunks(chunks, chunks)
    49→	verified := trie.VerifyMerkleProof(root, chunks[0][:], blob.Index+KZGOffset, blob.CommitmentInclusionProof)
    50→	if !verified {
    51→		return errInvalidInclusionProof
    52→	}
    53→	return nil
    54→}
    55→
    56→// MerkleProofKZGCommitment constructs a Merkle proof of inclusion of the KZG
    57→// commitment of index `index` into the Beacon Block with the given `body`
    58→func MerkleProofKZGCommitment(body interfaces.ReadOnlyBeaconBlockBody, index int) ([][]byte, error) {
    59→	bodyVersion := body.Version()
    60→	if bodyVersion < version.Deneb {
    61→		return nil, errUnsupportedBeaconBlockBody
    62→	}
    63→	commitments, err := body.BlobKzgCommitments()
    64→	if err != nil {
    65→		return nil, err
    66→	}
    67→	proof, err := bodyProof(commitments, index)
    68→	if err != nil {
    69→		return nil, err
    70→	}
    71→	membersRoots, err := topLevelRoots(body)
    72→	if err != nil {
    73→		return nil, err
    74→	}
    75→	sparse, err := trie.GenerateTrieFromItems(membersRoots, logBodyLength)
    76→	if err != nil {
    77→		return nil, err
    78→	}
    79→	topProof, err := sparse.MerkleProof(kzgPosition)
    80→	if err != nil {
    81→		return nil, err
    82→	}
    83→	// sparse.MerkleProof always includes the length of the slice this is
    84→	// why we remove the last element that is not needed in topProof
    85→	proof = append(proof, topProof[:len(topProof)-1]...)
    86→	return proof, nil
    87→}
    88→
    89→// PrecomputeMerkleProofComponents pre-computes the expensive parts of Merkle proof generation
    90→// that are shared across all blob indices for a given block body.
    91→func PrecomputeMerkleProofComponents(body interfaces.ReadOnlyBeaconBlockBody) (*MerkleProofComponents, error) {
    92→	bodyVersion := body.Version()
    93→	if bodyVersion < version.Deneb {
    94→		return nil, errUnsupportedBeaconBlockBody
    95→	}
    96→
    97→	// Pre-compute KZG subtree
    98→	commitments, err := body.BlobKzgCommitments()
    99→	if err != nil {
   100→		return nil, err
   101→	}
   102→
   103→	// No work needed if there are no commitments
   104→	if len(commitments) == 0 {
   105→		return nil, nil
   106→	}
   107→
   108→	leaves := LeavesFromCommitments(commitments)
   109→	kzgSubtree, err := trie.GenerateTrieFromItems(leaves, field_params.LogMaxBlobCommitments)
   110→	if err != nil {
   111→		return nil, err
   112→	}
   113→
   114→	// Pre-compute top-level components
   115→	membersRoots, err := topLevelRoots(body)
   116→	if err != nil {
   117→		return nil, err
   118→	}
   119→	topLevelTrie, err := trie.GenerateTrieFromItems(membersRoots, logBodyLength)
   120→	if err != nil {
   121→		return nil, err
   122→	}
   123→	topLevelProof, err := topLevelTrie.MerkleProof(kzgPosition)
   124→	if err != nil {
   125→		return nil, err
   126→	}
   127→	// Remove the last element that is not needed in topProof
   128→	topLevelProof = topLevelProof[:len(topLevelProof)-1]
   129→
   130→	return &MerkleProofComponents{
   131→		kzgSubtree:    kzgSubtree,
   132→		topLevelProof: topLevelProof,
   133→	}, nil
   134→}
   135→
   136→// MerkleProofKZGCommitmentFromComponents constructs a Merkle proof for a specific index
   137→// using pre-computed components, avoiding redundant calculations.
   138→func MerkleProofKZGCommitmentFromComponents(components *MerkleProofComponents, index int) ([][]byte, error) {
   139→	// Generate index-specific proof from pre-computed KZG subtree
   140→	subtreeProof, err := components.kzgSubtree.MerkleProof(index)
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→
   145→	// Combine with pre-computed top-level proof
   146→	proof := append(subtreeProof, components.topLevelProof...)
   147→	return proof, nil
   148→}
   149→
   150→// MerkleProofKZGCommitments constructs a Merkle proof of inclusion of the KZG
   151→// commitments into the Beacon Block with the given `body`
   152→func MerkleProofKZGCommitments(body interfaces.ReadOnlyBeaconBlockBody) ([][]byte, error) {
   153→	bodyVersion := body.Version()
   154→	if bodyVersion < version.Deneb {
   155→		return nil, errUnsupportedBeaconBlockBody
   156→	}
   157→
   158→	membersRoots, err := topLevelRoots(body)
   159→	if err != nil {
   160→		return nil, errors.Wrap(err, "top level roots")
   161→	}
   162→
   163→	sparse, err := trie.GenerateTrieFromItems(membersRoots, logBodyLength)
   164→	if err != nil {
   165→		return nil, errors.Wrap(err, "generate trie from items")
   166→	}
   167→
   168→	proof, err := sparse.MerkleProof(kzgPosition)
   169→	if err != nil {
   170→		return nil, errors.Wrap(err, "merkle proof")
   171→	}
   172→
   173→	// Remove the last element as it is a mix in with the number of
   174→	// elements in the trie.
   175→	proof = proof[:len(proof)-1]
   176→
   177→	return proof, nil
   178→}
   179→
   180→// LeavesFromCommitments hashes each commitment to construct a slice of roots
   181→func LeavesFromCommitments(commitments [][]byte) [][]byte {
   182→	leaves := make([][]byte, len(commitments))
   183→	for i, kzg := range commitments {
   184→		chunk := makeChunk(kzg)
   185→		gohashtree.HashChunks(chunk, chunk)
   186→		leaves[i] = chunk[0][:]
   187→	}
   188→	return leaves
   189→}
   190→
   191→// makeChunk constructs a chunk from a KZG commitment.
   192→func makeChunk(commitment []byte) [][32]byte {
   193→	chunk := make([][32]byte, 2)
   194→	copy(chunk[0][:], commitment)
   195→	copy(chunk[1][:], commitment[field_params.RootLength:])
   196→	return chunk
   197→}
   198→
   199→// bodyProof returns the Merkle proof of the subtree up to the root of the KZG
   200→// commitment list.
   201→func bodyProof(commitments [][]byte, index int) ([][]byte, error) {
   202→	if index < 0 || index >= len(commitments) {
   203→		return nil, errInvalidIndex
   204→	}
   205→	leaves := LeavesFromCommitments(commitments)
   206→	sparse, err := trie.GenerateTrieFromItems(leaves, field_params.LogMaxBlobCommitments)
   207→	if err != nil {
   208→		return nil, err
   209→	}
   210→	proof, err := sparse.MerkleProof(index)
   211→	if err != nil {
   212→		return nil, err
   213→	}
   214→	return proof, err
   215→}
   216→
   217→// topLevelRoots computes the slice with the roots of each element in the
   218→// BeaconBlockBody. Notice that the KZG commitments root is not needed for the
   219→// proof computation thus it's omitted
   220→func topLevelRoots(body interfaces.ReadOnlyBeaconBlockBody) ([][]byte, error) {
   221→	layer := make([][]byte, bodyLength)
   222→	for i := range layer {
   223→		layer[i] = make([]byte, 32)
   224→	}
   225→
   226→	// Randao Reveal
   227→	randao := body.RandaoReveal()
   228→	root, err := ssz.MerkleizeByteSliceSSZ(randao[:])
   229→	if err != nil {
   230→		return nil, err
   231→	}
   232→	copy(layer[0], root[:])
   233→
   234→	// eth1_data
   235→	eth1 := body.Eth1Data()
   236→	root, err = eth1.HashTreeRoot()
   237→	if err != nil {
   238→		return nil, err
   239→	}
   240→	copy(layer[1], root[:])
   241→
   242→	// graffiti
   243→	root = body.Graffiti()
   244→	copy(layer[2], root[:])
   245→
   246→	// Proposer slashings
   247→	ps := body.ProposerSlashings()
   248→	root, err = ssz.MerkleizeListSSZ(ps, params.BeaconConfig().MaxProposerSlashings)
   249→	if err != nil {
   250→		return nil, err
   251→	}
   252→	copy(layer[3], root[:])
   253→
   254→	// Attester slashings
   255→	as := body.AttesterSlashings()
   256→	bodyVersion := body.Version()
   257→	if bodyVersion < version.Electra {
   258→		root, err = ssz.MerkleizeListSSZ(as, params.BeaconConfig().MaxAttesterSlashings)
   259→	} else {
   260→		root, err = ssz.MerkleizeListSSZ(as, params.BeaconConfig().MaxAttesterSlashingsElectra)
   261→	}
   262→	if err != nil {
   263→		return nil, err
   264→	}
   265→	copy(layer[4], root[:])
   266→
   267→	// Attestations
   268→	att := body.Attestations()
   269→	if bodyVersion < version.Electra {
   270→		root, err = ssz.MerkleizeListSSZ(att, params.BeaconConfig().MaxAttestations)
   271→	} else {
   272→		root, err = ssz.MerkleizeListSSZ(att, params.BeaconConfig().MaxAttestationsElectra)
   273→	}
   274→	if err != nil {
   275→		return nil, err
   276→	}
   277→	copy(layer[5], root[:])
   278→
   279→	// Deposits
   280→	dep := body.Deposits()
   281→	root, err = ssz.MerkleizeListSSZ(dep, params.BeaconConfig().MaxDeposits)
   282→	if err != nil {
   283→		return nil, err
   284→	}
   285→	copy(layer[6], root[:])
   286→
   287→	// Voluntary Exits
   288→	ve := body.VoluntaryExits()
   289→	root, err = ssz.MerkleizeListSSZ(ve, params.BeaconConfig().MaxVoluntaryExits)
   290→	if err != nil {
   291→		return nil, err
   292→	}
   293→	copy(layer[7], root[:])
   294→
   295→	// Sync Aggregate
   296→	sa, err := body.SyncAggregate()
   297→	if err != nil {
   298→		return nil, err
   299→	}
   300→	root, err = sa.HashTreeRoot()
   301→	if err != nil {
   302→		return nil, err
   303→	}
   304→	copy(layer[8], root[:])
   305→
   306→	// Execution Payload
   307→	ep, err := body.Execution()
   308→	if err != nil {
   309→		return nil, err
   310→	}
   311→	root, err = ep.HashTreeRoot()
   312→	if err != nil {
   313→		return nil, err
   314→	}
   315→	copy(layer[9], root[:])
   316→
   317→	// BLS Changes
   318→	bls, err := body.BLSToExecutionChanges()
   319→	if err != nil {
   320→		return nil, err
   321→	}
   322→	root, err = ssz.MerkleizeListSSZ(bls, params.BeaconConfig().MaxBlsToExecutionChanges)
   323→	if err != nil {
   324→		return nil, err
   325→	}
   326→	copy(layer[10], root[:])
   327→
   328→	// KZG commitments is not needed
   329→
   330→	// Execution requests
   331→	if body.Version() >= version.Electra {
   332→		er, err := body.ExecutionRequests()
   333→		if err != nil {
   334→			return nil, err
   335→		}
   336→		root, err = er.HashTreeRoot()
   337→		if err != nil {
   338→			return nil, err
   339→		}
   340→		copy(layer[12], root[:])
   341→	}
   342→	return layer, nil
   343→}
